import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.BFXjnKeG.js";var i=JSON.parse(`{"title":"ログイン・アカウント・招待","description":"","frontmatter":{},"headers":[],"relativePath":"guides/accounts.md","filePath":"guides/accounts.md","lastUpdated":1793464466000}`),a={name:`guides/accounts.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ログイン・アカウント・招待" tabindex="-1">ログイン・アカウント・招待 <a class="header-anchor" href="#ログイン・アカウント・招待" aria-label="Permalink to “ログイン・アカウント・招待”">​</a></h1><h2 id="ログインする" tabindex="-1">ログインする <a class="header-anchor" href="#ログインする" aria-label="Permalink to “ログインする”">​</a></h2><p>管理画面でメールを入力し、パスキーでログインします。端末の顔・指紋・PIN、または対応するセキュリティキーで本人確認します。メールアドレスはログインIDです。</p><p>Cloudflare Accessで保護した確認環境では、先にAccessのメールコード等で入場します。これはJevSenseのパスキーとは別の入口です。</p><h2 id="初めて使う" tabindex="-1">初めて使う <a class="header-anchor" href="#初めて使う" aria-label="Permalink to “初めて使う”">​</a></h2><p><strong>環境の最初の管理者</strong>は、表示名・メール・初回ADMIN_TOKENでパスキーを登録します。最初のユーザーはSuperuserです。Accessに連携したPreviewでは、認証済みメールに固定して登録し、共有トークンは入力しません。</p><p><strong>招待された方</strong>は、管理者から受け取ったリンクを開いて表示名とパスキーを登録します。リンクは24時間・1回限りです。期限切れなら管理者に再発行を依頼します。</p><p>既存アカウントがある場合は、そのパスキーでログインして招待を受けます。サイトごとにアカウントやパスキーを作り直す必要はありません。</p><h2 id="表示名とパスキーを管理する" tabindex="-1">表示名とパスキーを管理する <a class="header-anchor" href="#表示名とパスキーを管理する" aria-label="Permalink to “表示名とパスキーを管理する”">​</a></h2><p>左下のアカウントから表示名を変更できます。全サイトで共通の名前であり、ログインIDや権限は変わりません。メールアドレス変更は今回の機能に含みません。</p><p><img src="/jev-personalization/images/account.png" alt="アカウント設定" width="1440" height="1050"></p><p>「別のパスキーを追加」で予備の端末やキーも登録します。最後の1つは削除できません。重要な操作では5分以内のパスキー本人確認を求めます。</p><h2 id="権限とサイトの切り替え" tabindex="-1">権限とサイトの切り替え <a class="header-anchor" href="#権限とサイトの切り替え" aria-label="Permalink to “権限とサイトの切り替え”">​</a></h2><table tabindex="0"><thead><tr><th>権限</th><th>主な範囲</th></tr></thead><tbody><tr><td>Superuser</td><td>全サイト・全ユーザー・環境設定</td></tr><tr><td>サイト管理者</td><td>所属サイトの施策・設定・デザイン・メンバー・独自コード</td></tr><tr><td>編集者</td><td>所属サイトの標準施策の作成・配信・確認</td></tr><tr><td>閲覧者</td><td>所属サイトの参照</td></tr></tbody></table><p>複数サイトに所属している場合、上部ヘッダーで切り替えます。サイトごとに権限が異なることもあります。表示されないサイトは、管理者へ所属を確認してください。</p><h2 id="メンバーを招待する" tabindex="-1">メンバーを招待する <a class="header-anchor" href="#メンバーを招待する" aria-label="Permalink to “メンバーを招待する”">​</a></h2><p>サイト管理者は「メンバー」からメールと権限を指定し、招待リンクを本人へ共有します。メールは自動送信しません。メールの所有確認が自動で完了したという意味でもありません。</p><p>同じメールへの再発行では、以前のリンクを無効にします。不要な招待は取り消します。登録済みメンバーの権限変更は、招待のやり直しではなくメンバー一覧から行います。</p><h2 id="端末を失った場合" tabindex="-1">端末を失った場合 <a class="header-anchor" href="#端末を失った場合" aria-label="Permalink to “端末を失った場合”">​</a></h2><p>まず別の登録済みパスキーを試します。使えない場合は「パスキーが使えない場合」から、事前に保存した復旧コードで新しいパスキーを登録します。</p><p>復旧コードは8個、発行時だけ表示します。再発行すると旧コードは無効です。復旧完了時には旧パスキー・全ログイン・残りのコードも無効になるので、新しいコードを発行してください。</p><p>コードもない場合は、Superuserへ本人確認と5分・1回限りの復旧リンクの発行を依頼します。最後の有効なSuperuserは無効化・降格できません。</p><h2 id="ログインの期限" tabindex="-1">ログインの期限 <a class="header-anchor" href="#ログインの期限" aria-label="Permalink to “ログインの期限”">​</a></h2><p>無操作30分、ログインから12時間で再ログインが必要です。「他のログインをすべて終了」では、このブラウザ以外のログインを終了できます。ユーザー停止・全体権限変更・復旧でもセッションを無効にします。</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};